class Solution {
public:
    int minCapability(std::vector<int>& nums, int k) {
        int lo = *std::min_element(nums.begin(), nums.end());
        int hi = *std::max_element(nums.begin(), nums.end());
        int n = nums.size();
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            int cnt = 0;
            int i = 0;
            while (i < n) {
                if (nums[i] <= mid) {
                    cnt++;
                    i += 2;
                } else {
                    i++;
                }
            }
            if (cnt >= k) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

class Solution {
    public int minCapability(int[] nums, int k) {
        int lo = nums[0], hi = nums[0];
        for (int x : nums) {
            lo = Math.min(lo, x);
            hi = Math.max(hi, x);
        }
        int n = nums.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            int cnt = 0;
            int i = 0;
            while (i < n) {
                if (nums[i] <= mid) {
                    cnt++;
                    i += 2;
                } else {
                    i++;
                }
            }
            if (cnt >= k) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

var minCapability = function(nums, k) {
    let lo = nums[0], hi = nums[0];
    for (const x of nums) {
        if (x < lo) lo = x;
        if (x > hi) hi = x;
    }
    const n = nums.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        let cnt = 0;
        let i = 0;
        while (i < n) {
            if (nums[i] <= mid) {
                cnt++;
                i += 2;
            } else {
                i++;
            }
        }
        if (cnt >= k) hi = mid;
        else lo = mid + 1;
    }
    return lo;
};
